package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaSwDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus (Rukuu na Sujuud)", "(Mwenyezi Mungu ni) Ametakasika, Mtakatifu zaidi, Mola wa Malaika na Roho (Jibril).", "Katika rukuu na sujuud.", "Mtume ﷺ amekariri haya kwa rukuu na sujuud."),
        "dua_sujood_dhanbi_kullah" to DuaText("Katika Sujood: Nisamehe Dhambi Zangu Zote", "Ewe Mwenyezi Mungu, nighufirie madhambi yangu yote, madogo na makubwa, ya kwanza na ya mwisho, yaliyo wazi na yaliyofichika.", "Katika sujood.", "Kusujudu ni mahali ambapo dua hujibiwa."),
        "dua_sujood_ridaka" to DuaText("Kimbilio katika Raha Yako", "Ewe Mwenyezi Mungu, najikinga kwa radhi Yako kutokana na hasira Yako, na msamaha Wako na adhabu Yako, na najikinga Kwako kutokana na Wewe. Siwezi kukusifu Wewe kikamilifu; Wewe ni kama Ulivyojisifu.", "Katika sujuud - Aisha (RA) alimsikia Mtume ﷺ akisema hivi.", "Sujuud dua ya Mtume ﷺ."),
        "dua_tashahhud" to DuaText("Tashahhud (At-Tahiyyat)", "Ibada zote za maneno, kimwili na kifedha ni za Mwenyezi Mungu. Amani iwe juu yako, ewe Mtume, na rehema ya Mwenyezi Mungu na baraka zake. Amani iwe juu yetu na juu ya waja wema wa Mwenyezi Mungu. Nashuhudia ya kwamba hapana apasaye kuabudiwa kwa haki isipokuwa Mwenyezi Mungu, na nashuhudia kwamba Muhammad ﷺ ni mja na Mtume wake.", "Katika kila kikao - imesimuliwa na Abdullah ibn Mas'ud (RA) (mazoezi ya Hanafi).", "Mtume ﷺ aliifundisha kama surah ya Quran."),
        "dua_sajdah_tilawah" to DuaText("Sajdah ya Kisomo", "Uso wangu umemsujudia yule aliyeuumba na akatoa kusikia kwake na kuona kwake kwa uwezo na uwezo wake.", "Katika sijda ya kisomo.", "Mtume ﷺ alisema haya katika sijda ya kisomo cha usiku."),
        "dua_after_witr" to DuaText("Baada ya Witr", "Ametakasika Mfalme, Mtakatifu Zaidi.", "Mara tatu baada ya salam ya witr, kuinua sauti mara ya tatu.", "Mtume ﷺ alisema haya baada ya witr."),
        "dua_tahajjud_nur" to DuaText("Dua ya Kufungua Tahajjud", "Ewe Mwenyezi Mungu, sifa njema ni Zako; Wewe ndiye Mlinzi wa mbingu na ardhi na vyote vilivyomo. Sifa njema ni Zako; Wewe ndiye Nuru ya mbingu na ardhi na vyote vilivyomo. Sifa njema ni Zako; Wewe ni Haki, Ahadi Yako ni kweli, kukutana na Wewe ni kweli, Neno Lako ni kweli, Pepo ni kweli, Jahannamu ni kweli, Mitume ni kweli, Muhammad ﷺ ni kweli na Saa ni kweli.", "Wakati wa kuanza sala ya usiku (tahajjud) (sehemu ya ufunguzi wa dua).", "Mtume ﷺ aliyasoma haya alipokuwa akiinuka kwa ajili ya tahajjud (dua kamili iko katika al-Bukhari)."),
        "dua_rabba_jibrail" to DuaText("Niongoze Katika Mambo Yanayobishaniwa", "Ewe Mwenyezi Mungu, Mola wa Jibril, Mikail na Israfil, Muumba wa mbingu na ardhi, Mjuzi wa ghaibu na yanayoonekana! Utahukumu baina ya waja wako katika yale waliyokuwa wakikhitalifiana. Niongoze kwa idhini Yako kwenye haki katika yale yaliyokhitalifiana. Hakika Wewe unamuongoza umtakaye kwenye Njia Iliyo Nyooka.", "Mwanzoni mwa tahajjud - kwa mwongozo wa ukweli katikati ya kutokubaliana.", "Mtume ﷺ alianza swala yake ya usiku kwa dua hii."),
        "dua_going_to_mosque_nur" to DuaText("Kwenda Msikitini (Dua ya Nuru)", "Ewe Mwenyezi Mungu, niweke nuru moyoni mwangu, nuru machoni mwangu, nuru masikioni mwangu, nuru upande wa kulia wangu, nuru kushoto kwangu, nuru juu yangu, nuru chini yangu, nuru mbele yangu, nuru nyuma yangu, na unifanyie nuru.", "Wakati wa kwenda msikitini kwa ajili ya Fajr.", "Mtume ﷺ alikariri haya wakati wa kwenda nje kwa ajili ya maombi."),
        "dua_waswasa_salah" to DuaText("Waswasa Wakati wa Swalah (Khinzab)", "Najikinga kwa Mwenyezi Mungu na Shet'ani aliyelaaniwa.", "Wakati minong'ono ya kishetani inapokuja wakati wa sala, tafuta hifadhi na kavu-temea mate kidogo upande wa kushoto mara tatu.", "Uthman ibn Abil-'As (RA) alifanya hivi na minong'ono ikaondoka."),
        "dua_alimal_ghayb" to DuaText("Mjuzi wa ghaibu", "Ewe Mwenyezi Mungu, Mjuzi wa ghaibu na yanayoonekana, Muumba wa mbingu na ardhi, Mola Mlezi wa kila kitu! Nashuhudia ya kwamba hapana mungu ila Wewe. Najikinga Kwako na shari ya nafsi yangu, na shari ya Shetani na shirki yake.", "Asubuhi, jioni na kabla ya kulala - Mtume ﷺ alimfundisha Abu Bakr (RA).", "Kinga dhidi ya shari ya nafsi na ya Shetani."),
        "dua_fitratil_islam" to DuaText("Juu ya Fitra ya Uislamu", "Tumeingia asubuhi juu ya fitra ya Uislamu, kwa neno la ikhlasi, juu ya Dini ya Mtume wetu Muhammad ﷺ na kwa njia ya baba yetu Ibrahim (AS), ambaye alikuwa mwongofu na Mwislamu, na hakuwa miongoni mwa washirikina.", "Asubuhi.", "Kufanya upya imani ya mtu kila asubuhi."),
        "dua_amsayna_fitrah" to DuaText("Jioni kwenye Fitrah ya Uislamu", "Tumeingia jioni kwenye fitra ya Uislamu, kwa neno la ikhlasi, juu ya dini ya Mtume wetu Muhammad ﷺ na kwa njia ya baba yetu Ibrahim (AS), ambaye alikuwa mwongofu na Mwislamu, na hakuwa miongoni mwa washirikina.", "Wakati wa jioni.", "Kufanya upya imani ya mtu kila jioni."),
        "dua_tahleel_10_fajr" to DuaText("Tahleel Kumi Baada ya Alfajiri na Maghrib", "Hapana apasae kuabudiwa kwa haki isipokuwa Mwenyezi Mungu, peke yake, asiye na mshirika. Ufalme ni wake na sifa njema ni zake. Anahuisha na anafisha, na Yeye ni Muweza wa kila kitu.", "Mara kumi baada ya Alfajiri (na Maghrib), kabla ya kutoka kwenye kikao chako au kuzungumza.", "Amali kumi nzuri, dhambi kumi zimefutwa, daraja kumi zilizoinuliwa na ulinzi kutoka kwa Shetani siku nzima."),
        "dua_la_hawla_kanz" to DuaText("Hazina ya Jannah", "Hakuna nguvu wala uwezo ila kwa Mwenyezi Mungu.", "Mara nyingi, wakati wote.", "Ni moja ya hazina za Peponi."),
        "dua_four_beloved_words" to DuaText("Maneno Manne Yanayopendwa Zaidi", "Ametakasika Mwenyezi Mungu, sifa njema zote ni za Mwenyezi Mungu, hapana apasae kuabudiwa kwa haki isipokuwa Mwenyezi Mungu, na Mwenyezi Mungu ndiye Mkubwa.", "Maneno yanayopendwa zaidi na Mwenyezi Mungu.", "Wanapendwa zaidi na Mtume ﷺ kuliko kila lichomoza jua."),
        "dua_two_light_words" to DuaText("Maneno Mawili Mwanga kwenye Ulimi", "Ametakasika Mwenyezi Mungu na sifa njema zote ni zake; utukufu ni wa Mwenyezi Mungu Mtukufu.", "Mwanga kwa ulimi, mzito kwenye Mizani.", "Kipenzi cha Mwingi wa Rehema, mwepesi kwenye ulimi na mzito kwenye Mizani. (Hadithi ya mwisho ya al-Bukhari)"),
        "dua_ya_dhal_jalal" to DuaText("Ya Dhal-Jalali wal-Ikram", "Ewe Mwenye Enzi na Heshima!", "Shikilia kwa dua - maagizo ya Mtume ﷺ.", "Mtume ﷺ amesema: shikamaneni na 'Ya Dhal-Jalali wal-Ikram'."),
        "dua_sleep_wadatu_janbi" to DuaText("Kwa Jina Lako Najilaza", "Kwa jina lako, Bwana wangu, najilaza ubavu wangu na kwa jina lako nasimama. Ukiichukua nafsi yangu, irehemu, na ukiiachilia, ilinde kama unavyowalinda waja wako wema.", "Baada ya kutikisa vumbi kitandani na kujilaza.", "Kuikabidhi nafsi yako kwa Mwenyezi Mungu kabla ya kulala."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Umeiumba Nafsi Yangu", "Ewe Mwenyezi Mungu, Umeiumba nafsi yangu na Utaichukua. Kifo chake na uhai wake ni vyako. Ukiiweka hai basi ilinde, na ukiifisha basi isamehe. Ewe Mwenyezi Mungu, nakuomba kheri.", "Kabla ya kulala - imesimuliwa na Ibn Umar (RA).", "Mtume ﷺ aliagiza kusema hivi wakati wa kulala."),
        "dua_sleep_atamana" to DuaText("Shukrani Kabla ya Kulala", "Sifa njema zote ni za Mwenyezi Mungu ambaye alitulisha, akatupa kinywaji, akatutosheleza na akatupa makazi. Ni wangapi ambao hawana wa kuwatosheleza au kuwapa hifadhi.", "Wakati wa kwenda kulala.", "Mtume ﷺ alisema hivi alipokuwa anaenda kulala."),
        "dua_sleep_rabbas_samawat" to DuaText("Bwana wa Mbingu - Lipa Deni Letu", "Ewe Mwenyezi Mungu, Mola Mlezi wa mbingu, ardhi na Arshi yenye nguvu, Mola wetu Mlezi na Mola wa kila kitu, Mpasuaji wa mbegu na tende, Mteremshi wa Taurati, Injil na Furqan! Najikinga Kwako kutokana na shari ya kila kitu ambacho Unashikilia kisogo chake. Ewe Mwenyezi Mungu, Wewe ndiye wa Kwanza, hakuna kitu mbele Yako; Wewe ndiye wa Mwisho, hakuna kitu baada Yako; Wewe ndiwe Dhahiri, hakuna kitu juu Yako; Wewe ndiye uliyefichika, hakuna kinachofichika Kwako. Utulipe deni letu na utukomboe kutoka kwa umaskini.", "Kabla ya kulala, kulala upande wa kulia - alifundishwa kwa Fatimah (RA).", "Dua ya msamaha kutoka kwa deni na shida."),
        "dua_sleep_fear" to DuaText("Hofu au Kufadhaika katika Usingizi", "Najikinga na maneno ya Mwenyezi Mungu yaliyo kamili kutokana na hasira yake na adhabu yake, na shari ya waja wake, na minong'ono ya mashetani na kunijia kwao.", "Wakati wa kuhisi hofu au wasiwasi katika usingizi.", "Kufanya hivyo, jambo hilo halitamdhuru."),
        "dua_waking_afani" to DuaText("Kuamka: Aliirejesha Nafsi Yangu", "Sifa njema zote ni za Mwenyezi Mungu ambaye aliujaalia mwili wangu kheri, akanirudishia nafsi yangu na akaniruhusu kumkumbuka.", "Wakati wa kuamka.", "Asante kwa asubuhi mpya."),
        "dua_allahu_rabbi" to DuaText("Mwenyezi Mungu, Mwenyezi Mungu ni Mola Wangu", "Mwenyezi Mungu, Mwenyezi Mungu ni Mola wangu Mlezi; Mimi simshirikishi na chochote.", "Katika huzuni au dhiki - Mtume ﷺ alimfundisha Asma binti Umays (RA).", "Kushikilia tawhid wakati wa dhiki."),
        "dua_rahmataka_arju" to DuaText("Rehema Zako Natumaini", "Ewe Mwenyezi Mungu, ni rehema zako ninazozitarajia, basi usiniache peke yangu hata kwa kupepesa macho, na urekebishe mambo yangu yote. Hapana mungu ila Wewe.", "Dua ya mwenye dhiki (Da'awat al-makrub).", "Mtume ﷺ aliiita dua ya mwenye dhiki."),
        "dua_against_enemy_ahzab" to DuaText("Dhidi ya Majeshi ya Adui", "Ewe Mwenyezi Mungu, Mteremshi wa Kitabu, Mwepesi wa kuhisabu! Washinde washiriki. Ewe Mwenyezi Mungu washinde na watikise.", "Dhidi ya adui - dua ya Vita vya Mashirikisho.", "Dua ya Mtume ﷺ dhidi ya adui."),
        "dua_anta_adudi" to DuaText("Wewe Ni Msaada Wangu", "Ewe Mwenyezi Mungu, Wewe ndiye tegemeo langu na msaidizi wangu. Kwa Wewe ninapanga, Kwako natangulia na Kwako napigana.", "Kabla ya mashindano au changamoto kubwa.", "Mtume ﷺ alisema hivi katika vita."),
        "dua_ikfinihim" to DuaText("Inatosha Mimi Dhidi Yao", "Ewe Mwenyezi Mungu, nitoshe mimi dhidi yao upendavyo.", "Dhidi ya uovu wa madhalimu - dua ya kijana katika hadithi ya Watu wa Shimoni.", "Mwenyezi Mungu alimuokoa kijana kutoka kwa madhalimu."),
        "dua_qadarullah" to DuaText("Wakati Kitu Kibaya Kinapotokea", "Ni hukumu ya Mwenyezi Mungu, na akafanya apendavyo.", "Wakati jambo lisilopendeza linapotokea, badala ya kusema 'kama tu'.", "'Laiti tu' hufungua mlango kwa Shetani."),
        "dua_ala_kulli_hal" to DuaText("Sifa Katika Kila Hali", "Sifa njema zote ni za Mwenyezi Mungu kwa kila hali.", "Wakati kitu kisichopendwa kinatokea.", "Mtume ﷺ alisema haya juu ya kukabiliana na jambo asilolipenda."),
        "dua_dogs_barking" to DuaText("Kusikia Mbwa Hubweka Usiku", "Najikinga kwa Mwenyezi Mungu na Shet'ani aliyelaaniwa.", "Kwa kusikia mbwa wakibweka au punda hulia usiku.", "Wanaona usicho kiona."),
        "dua_leaving_home_adilla" to DuaText("Kimbilio dhidi ya Kupotea", "Ewe Mwenyezi Mungu, najikinga Kwako nisije nikapotea au nikapotezwa, nisije nikateleza au niteleze, nisije nikadhulumu au nikadhulumiwa, nisije nikafanya upumbavu au nikapumbazika.", "Wakati wa kuondoka nyumbani - imesimuliwa na Umm Salamah (RA).", "Mtume ﷺ alikariri haya kila alipotoka nyumbani kwake."),
        "dua_ascending_descending" to DuaText("Kwenda Juu na Kushuka", "Mwenyezi Mungu ndiye Mkubwa (wakati wa kwenda juu). - Ametakasika Mwenyezi Mungu (wakati wa kushuka).", "Ukiwa safarini, sema 'Allahu Akbar' unapopanda na 'SubhanAllah' unaposhuka.", "Tabia ya Maswahaba (RA) wakiwa safarini."),
        "dua_traveller_sahar" to DuaText("Dua ya Msafiri Kabla ya Alfajiri", "Mwenye kusikia amesikia (na kupitisha) sifa zetu za Mwenyezi Mungu na neema zake juu yetu. Mola wetu Mlezi, tufuate na utujaalie neema Yako, tukiomba hifadhi kwa Mwenyezi Mungu na Moto.", "Katika safari, kabla ya alfajiri.", "Mtume ﷺ alisema hayo kabla ya alfajiri alipokuwa safarini."),
        "dua_zawwadakallah" to DuaText("Kwa Msafiri: Mwenyezi Mungu Akupe Taqwa", "Mwenyezi Mungu akupe taqwa katika safari yako, akusamehe madhambi yako na akufanyie wepesi kheri popote ulipo.", "Wakati wa kumuaga msafiri.", "Mtume ﷺ alitoa dua hii kwa mtu anayetoka safarini."),
        "dua_traveller_to_resident" to DuaText("Msafiri kwa Waliobaki Nyuma", "Nakukabidhi kwa Mwenyezi Mungu ambaye kwake amana hazipotei.", "Alisema msafiri wakati wa kuaga familia.", "Kukabidhi usalama wa familia kwa Mwenyezi Mungu."),
        "dua_entering_village" to DuaText("Kuingia katika Mji au Kijiji", "Ewe Mwenyezi Mungu, Mola Mlezi wa mbingu saba na vivuli vyote vilivyomo, Mola Mlezi wa ardhi saba na vyote wanavyovibeba, Mola Mlezi wa mashetani na wanavyovipoteza, Mola Mlezi wa pepo na vyote vinavyowatawanya. Tunakuomba kheri ya mji huu na watu wake, na tunajikinga Kwako na shari yake, na shari ya watu wake na shari ya yaliyomo ndani yake.", "Kabla ya kuingia mji au jiji.", "Mtume ﷺ alikariri haya kila alipotaka kuingia katika mji."),
        "dua_vehicle_stumbles" to DuaText("Wakati Gari Inajikwaa", "Kwa jina la Mwenyezi Mungu.", "Wakati mlima au gari linapoteleza au kujikwaa, badala ya kusema 'Shetani na aangamie'.", "Kusema Bismillah humfanya Shaytan anyenyekee hadi kufikia ukubwa wa nzi."),
        "dua_ajz_kasal_haram" to DuaText("Kimbilio kutoka kwa Udhaifu na Uzee", "Ewe Mwenyezi Mungu, najikinga Kwako kutokana na unyonge na uvivu, na woga na uzee, na mitihani ya maisha na mauti, na adhabu ya kaburi.", "Dua ya kina ya kila siku ya kimbilio.", "A dua Mtume ﷺ alifanya mara kwa mara."),
    )
}
